INSERT INTO src VALUES
  ('The Marshall Islands Journal', 'https://marshallislandsjournal.com', 'https://marshallislandsjournal.com/feed/', 'marshallislandsjournal.com', 'rss, 10 items, newest 2026-10-15', $$Hebdomadaire privé$$, $$Propriété privée ; rédacteur en chef Giff Johnson (depuis 1984)$$, $$Fondé le 13 février 1970 sous le nom de Micronitor par Joe Murphy et Mike Malone, volontaires du Peace Corps ; devenu The Marshall Islands Journal. Seul journal du pays, bilingue anglais-marshallais, environ 2 000 exemplaires par semaine (2018).$$, $$Journal indépendant, connu dès ses débuts pour ses critiques des responsables micronésiens et de l'administration américaine du Territoire sous tutelle ; suit de près les conséquences des essais nucléaires. Le Département d'État américain le cite comme une source majeure sur les Îles Marshall.$$, $$Fondation, propriété, direction et indépendance documentées par Wikipédia.$$, $$[{"url": "https://en.wikipedia.org/wiki/Marshall_Islands_Journal", "note": "Fondé en 1970 (Micronitor) ; privé ; rédacteur en chef Giff Johnson ; hebdomadaire, seul journal du pays ; indépendant", "category": "reference", "accessed_at": "2026-10-19"}]$$::jsonb);
DO $$
DECLARE mm int; bad int; n int; s record; sid int; pid int;
BEGIN
  -- Marshall Islands source (same refusal as findPublisherConflict, plus an earlier run of this script)
  SELECT id INTO mm FROM countries WHERE iso_code = 'MH';
  IF mm IS NULL THEN RAISE EXCEPTION 'no MH country'; END IF;
  SELECT count(*) INTO bad FROM src x
   WHERE EXISTS (SELECT 1 FROM publishers p WHERE p.country_id = mm AND (lower(p.name) = lower(x.name)
                 OR lower(regexp_replace(regexp_replace(p.domain, '^www[.]', ''), '/+$', '')) = x.domain))
      OR EXISTS (SELECT 1 FROM feeds f WHERE f.feed_url = x.feed)
      OR EXISTS (SELECT 1 FROM publisher_submissions ps WHERE ps.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #102 Marshall Islands Journal]');
  IF bad > 0 THEN RAISE EXCEPTION '% of 1 already exist as a publisher, feed or earlier run - nothing changed', bad; END IF;
  n := 0;
  FOR s IN SELECT * FROM src ORDER BY name LOOP
    INSERT INTO publisher_submissions (name, homepage_url, feed_url, feed_type, country_id, language, feed_verified,
      verification_detail, domain, ingestion_method, status, status_changed_at, reviewed_at)
    VALUES (s.name, s.homepage, s.feed, 'rss', mm, 'en', true,
      'Feed checked 2026-10-19: ' || s.note || ' ' || '[added by Claude 2026-10-19, Build #102 Marshall Islands Journal]', s.domain, 'feed', 'approved', now(), now())
    RETURNING id INTO sid;
    INSERT INTO publishers (country_id, name, homepage_url, feed_status, language, domain, source_type)
    VALUES (mm, s.name, s.homepage, 'active', 'en', s.domain, 'ONLINE_NEWS') RETURNING id INTO pid;
    INSERT INTO feeds (publisher_id, feed_url, feed_type) VALUES (pid, s.feed, 'rss');
    UPDATE publisher_submissions SET publisher_id = pid WHERE id = sid;
    INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
      current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
    VALUES (pid, s.ownership_type, s.owner, ARRAY['independent']::text[], NULL, s.historical_context, s.current_context, 'high',
      s.evidence_summary, s.evidence_sources, DATE '2026-10-19', DATE '2026-10-19', DATE '2026-10-19', false);
    n := n + 1;
